//! MP `usercmd_t::buttons` bit flags, copied from Raven `codemp/game/q_shared.h`.
//!
//! Raven comment: `usercmd_t->button bits, many of which are generated by the
//! client system, so they aren't game/cgame only definitions`.
//! Source: `oracle/oracle/codemp/game/q_shared.h:2447-2470`

use core::ffi::c_int;

pub const BUTTON_ATTACK: c_int = 1;
/// displays talk balloon and disables actions
pub const BUTTON_TALK: c_int = 2;
pub const BUTTON_USE_HOLDABLE: c_int = 4;
pub const BUTTON_GESTURE: c_int = 8;
/// walking can't just be infered from MOVE_RUN because a key pressed late in
/// the frame will only generate a small move value for that frame; walking
/// will use different animations and won't generate footsteps
pub const BUTTON_WALKING: c_int = 16;
/// the ol' use key returns!
pub const BUTTON_USE: c_int = 32;
pub const BUTTON_FORCEGRIP: c_int = 64;
pub const BUTTON_ALT_ATTACK: c_int = 128;
/// any key whatsoever
pub const BUTTON_ANY: c_int = 256;
/// use the "active" force power
pub const BUTTON_FORCEPOWER: c_int = 512;
pub const BUTTON_FORCE_LIGHTNING: c_int = 1024;
pub const BUTTON_FORCE_DRAIN: c_int = 2048;

// Raven kept a second, `#if 0`-style block of bot-gesture BUTTON_* defines
// (BUTTON_AFFIRMATIVE/NEGATIVE/GETFLAG/GUARDBASE/PATROL/FOLLOWME) commented
// out in source with the note "I ripped them out ... We can always add some
// back in if we want though." Dead in Raven itself; dropped per
// porting-rules §20 (drop dead surface).
// Source: `oracle/oracle/codemp/game/q_shared.h:2472-2483`
